insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('JP:civil-engineer','2026-08-10',0,0,0,0,12,0,0,0,3,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Civil Engineer spans MHLW 008-04 civil design, 008-05 civil construction management and 008-06 other civil engineering; no false single rollup is assigned.','entry_level_basis','Civil-engineering study and graduate engineering pathways provide structured entry, with practical project experience important.','qualification_note','The occupation is not universally licensed, although legally designated construction-site engineer appointments can require recognised qualifications or experience.','market_scope','No exact recurring canonical civil-engineer market series is normalised yet.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-10'),
('JP:mechanical-engineer','2026-08-10',0,0,0,0,12,0,0,0,3,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Mechanical Engineer spans 006-03 mechanical development/design and 007-04 mechanical manufacturing engineering.','entry_level_basis','Mechanical-engineering degrees and graduate technical roles provide a structured route, with design and production experience valued.','qualification_note','No single personal licence is required across the full occupation.','market_scope','Development and manufacturing groups are not blended into a fabricated exact labour-market series.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-10'),
('JP:electrical-engineer','2026-08-10',0,0,0,0,12,0,0,0,2,14,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Electrical Engineer spans 006-02 electrical/electronic development, 007-02 electrical/electronic manufacturing and facility engineering, and selected 007-03 electrical-construction engineering scope.','entry_level_basis','Electrical and electronic engineering study provides a structured professional entry route.','qualification_note','The occupation is not universally licensed, but specified electrical facilities require appointment of a qualified 電気主任技術者 and some construction responsibilities have separate statutory requirements.','market_scope','The distinct official groups are not merged into a fabricated exact employment or vacancy series.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-10'),
('JP:manufacturing-engineer','2026-08-10',0,0,0,0,12,0,0,0,3,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Manufacturing engineering is sector-specific in the MHLW 007 family rather than one generic occupation, spanning production engineering for food, electrical/electronic, machinery, automotive, transport equipment, materials, chemicals and other manufacturing.','entry_level_basis','Mechanical, materials, electrical, chemical and related engineering study can lead into production/process engineering; eleven reviewed programmes are retained as related rather than direct.','qualification_note','No universal personal manufacturing-engineer licence covers the full canonical role.','market_scope','Sector-specific 007 data are not combined into one invented generic manufacturing-engineer market series.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-10'),
('JP:industrial-engineer','2026-08-10',0,0,0,0,12,0,0,0,3,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Industrial Engineer has no standalone MHLW small-class code; process, productivity, quality and systems-improvement work is distributed across sector-specific manufacturing-engineering classifications.','entry_level_basis','Industrial, systems, operations and engineering study is relevant; the one reviewed Japanese industrial-engineering programme remains a direct academic pathway.','qualification_note','No universal personal industrial-engineer licence applies across the canonical scope.','market_scope','Sector-specific manufacturing classifications are retained as references only and not treated as an exact industrial-engineer market series.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-10'),
('JP:chemical-engineer','2026-08-10',0,0,0,0,12,0,0,0,3,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Chemical Engineer spans 006-07 chemical-product development engineering and 007-08 chemical-product manufacturing engineering.','entry_level_basis','Chemical engineering and applied chemistry degrees provide structured entry, with process, plant and product-development experience relevant.','qualification_note','No single personal licence is required for every chemical-engineering role; plant, safety and legally designated duties can carry separate requirements.','market_scope','Development and manufacturing groups are not blended into a fabricated exact canonical market series.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-10'),
('JP:environmental-engineer','2026-08-10',0,0,0,0,12,0,0,0,3,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Environmental Engineer has no standalone MHLW small-class code; environmental measurement/investigation can fall under 011-99 while environmental civil-infrastructure work can overlap 008-04 and 008-06.','entry_level_basis','Environmental, civil and related engineering study provides relevant entry pathways.','qualification_note','The canonical occupation is not universally licensed, although statutory measurements in specified workplaces must be performed by registered 作業環境測定士.','market_scope','Measurement and civil-engineering source groups are not merged into an invented exact environmental-engineer series.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-10'),
('JP:engineering-technician','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Japan does not provide one generic Engineering Technician small-class code matching the canonical cross-discipline role; technical drafting/support scopes such as 080-04 and 080-05 are retained only as references.','entry_level_basis','Technical colleges, vocational study and supervised engineering-support experience can provide practical entry without requiring a full professional-engineering role.','qualification_note','No universal personal engineering-technician licence covers the broad canonical occupation.','market_scope','Drafting and discipline-specific technician groups are not aggregated into a fabricated generic technician labour series.','visa_scope','No occupation-specific visa credit is assigned in this foundation phase.'),'2026-08-10')
